/* Test CLI, never a production file-loading API. Inputs are generated by the driver. */
#include "../image_fixture.h"
#include <rmlines/parser.h>
#include <rmlines/writer.h>
#include <rmrender/apple_document.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static uint8_t *read_file(const char *path, size_t *size) {
    FILE *f = fopen(path, "rb");
    if (!f) {
        perror(path);
        exit(2);
    }
    if (fseek(f, 0, SEEK_END) != 0)
        exit(2);
    long n = ftell(f);
    if (n < 0 || n > 10000000)
        exit(2);
    rewind(f);
    uint8_t *p = malloc((size_t)n + 1);
    if (!p)
        exit(2);
    if (fread(p, 1, (size_t)n, f) != (size_t)n)
        exit(2);
    fclose(f);
    p[n] = 0;
    *size = (size_t)n;
    return p;
}
static void write_file(const char *path, const uint8_t *bytes, size_t size) {
    FILE *f = fopen(path, "wb");
    if (!f) {
        perror(path);
        exit(2);
    }
    if (fwrite(bytes, 1, size, f) != size)
        exit(2);
    fclose(f);
}
static void page(const char *mode, const char *path) {
    rm_draft_point points[] = {
        {-160, 120, 0, 32, 0, 180}, {0, 170, 0, 36, 0, 200}, {150, 300, 0, 28, 0, 180}};
    if (!strcmp(mode, "overflow")) {
        points[0].x = -500;
        points[2].x = 600;
        points[2].y = 1200;
    }
    rm_pen_tool tool = RM_TOOL_FINELINER_1;
    if (!strcmp(mode, "pencil"))
        tool = RM_TOOL_PENCIL_2;
    if (!strcmp(mode, "stamp"))
        tool = RM_TOOL_PENCIL_1;
    if (!strcmp(mode, "bristle"))
        tool = RM_TOOL_PAINTBRUSH_1;
    if (!strcmp(mode, "streak"))
        tool = RM_TOOL_BALLPOINT_2;
    if (!strcmp(mode, "scratch"))
        tool = RM_TOOL_BALLPOINT_1;
    if (!strcmp(mode, "marker"))
        tool = RM_TOOL_HIGHLIGHTER_2;
    if (!strcmp(mode, "eraser"))
        tool = RM_TOOL_ERASER;
    rm_draft_stroke stroke = rm_draft_stroke_make(
        tool, tool == RM_TOOL_HIGHLIGHTER_2 ? RM_COLOR_YELLOW : RM_COLOR_BLACK, points, 3);
    stroke.thickness = 1;
    rm_draft_paragraph paragraph = {.text = "Hello, Привет", .has_style = true, .style = 1};
    rm_draft_image image = {
        .file = "own.png", .key = {1}, .x = -150, .y = 250, .width = 200, .height = 160};
    rm_page_draft draft = {.author = {1}, .sheet = {630, 946, 630, 946}, .column = {400, 1}};
    if (strcmp(mode, "blank") && strcmp(mode, "text") && strcmp(mode, "image")) {
        draft.strokes = &stroke;
        draft.stroke_count = 1;
    }
    if (!strcmp(mode, "text")) {
        draft.paragraphs = &paragraph;
        draft.paragraph_count = 1;
    }
    if (!strcmp(mode, "image")) {
        draft.images = &image;
        draft.image_count = 1;
    }
    uint8_t *bytes = nullptr;
    size_t size = 0;
    rm_error e = {0};
    if (rm_write_page(&draft, &bytes, &size, &e) != RM_OK) {
        fprintf(stderr, "write page failed\n");
        exit(2);
    }
    write_file(path, bytes, size);
    rm_bytes_free(bytes);
}
static void result(rmr_status status, rmr_error *e, rmr_buffer *out, const char *path) {
    if (status == RMR_OK)
        write_file(path, out->bytes, out->size);
    else
        fprintf(stderr, "%s\n", e->message);
    printf("{\"ok\":%s,\"status\":%u}\n", status == RMR_OK ? "true" : "false", (unsigned)status);
    rmr_buffer_free(out);
}
int main(int argc, char **argv) {
    if (argc < 2)
        return 2;
    if (!strcmp(argv[1], "page") && argc == 4) {
        page(argv[2], argv[3]);
        return 0;
    }
    if (!strcmp(argv[1], "image") && argc == 3) {
        write_file(argv[2], image_png, sizeof image_png);
        return 0;
    }
    if (!strcmp(argv[1], "writer") && argc == 6) {
        size_t size, overlay_size;
        uint8_t *bytes = read_file(argv[2], &size), *pdf = read_file(argv[3], &overlay_size);
        rmr_pdf_overlay overlay = {
            .pdf = pdf, .size = overlay_size, .transform = {1, 0, 0, 1, 0, 0}};
        if (!strcmp(argv[5], "expand")) {
            overlay.replace_box = true;
            overlay.box = (rmr_rect){-20, -10, 240, 340};
        }
        rmr_error e = {0};
        rmr_buffer out = {0};
        rmr_status status = rmr_pdf_incremental(bytes, size, &overlay, 1, nullptr, nullptr, nullptr,
                                                &out, nullptr, &e);
        result(status, &e, &out, argv[4]);
        free(bytes);
        free(pdf);
        return 0;
    }
    if (!strcmp(argv[1], "document") && argc == 8) {
        char path[4096];
        snprintf(path, sizeof path, "%s/manifest.txt", argv[2]);
        size_t n;
        char *manifest = (char *)read_file(path, &n);
        rmd_file files[64];
        uint8_t *storage[64];
        size_t count = 0;
        char *cursor = manifest;
        while (*cursor) {
            char *end = strchr(cursor, '\n');
            if (end)
                *end = 0;
            if (!*cursor)
                break;
            if (count == 64)
                return 2;
            snprintf(path, sizeof path, "%s/%s", argv[2], cursor);
            size_t size;
            storage[count] = read_file(path, &size);
            files[count] =
                (rmd_file){.name = {cursor, strlen(cursor)}, .data = {storage[count], size}};
            count++;
            if (!end)
                break;
            cursor = end + 1;
        }
        rmd_archive archive = {.files = files, .count = count};
        rmr_archive_document *doc = nullptr;
        rmr_error e = {0};
        rmr_buffer out = {0};
        rmr_apple_fonts *fonts = nullptr;
        rmr_template_store *templates = nullptr;
        rmr_page_resources resources = {0};
        rmr_status status = rmr_apple_fonts_create_directory(argv[4], nullptr, &fonts, &e);
        if (status == RMR_OK) {
            snprintf(path, sizeof path, "%s/../templates", argv[4]);
            status = rmr_template_store_create(path, nullptr, &templates, &e);
            resources.template = rmr_template_store_resolve;
            resources.template_context = templates;
        }
        if (status == RMR_OK)
            status = rmr_archive_document_create(&archive, argv[6], true, nullptr, &doc, &e);
        if (status == RMR_OK) {
            size_t maximum = (size_t)strtoull(argv[7], nullptr, 10);
            if (!strcmp(argv[5], "preserve"))
                status =
                    rmr_apple_document_pdf_preserving(doc, &resources, fonts, RMR_PAPER_A4, maximum,
                                                      nullptr, nullptr, nullptr, &out, nullptr, &e);
            else
                status = rmr_apple_document_pdf(doc, &resources, fonts, RMR_PAPER_A4, maximum,
                                                nullptr, nullptr, nullptr, &out, nullptr, &e);
        }
        result(status, &e, &out, argv[3]);
        rmr_apple_fonts_free(fonts);
        rmr_template_store_free(templates);
        rmr_archive_document_free(doc);
        for (size_t i = 0; i < count; i++)
            free(storage[i]);
        free(manifest);
        return 0;
    }
    return 2;
}
